function solve(s, k) {
  if (k <= 0) return s;
  if (k === 1) return "";
  let cur = s;
  while (true) {
    let removed = false;
    let i = 0;
    while (i < cur.length) {
      let j = i;
      while (j < cur.length && cur[j] === cur[i]) j++;
      if (j - i >= k) {
        cur = cur.slice(0, i) + cur.slice(i + k);
        removed = true;
        break;
      }
      i = j;
    }
    if (!removed) return cur;
  }
}

function solve(s, k) {
  if (k <= 0) return s;
  if (k === 1) return "";
  const stack = [];
  for (const ch of s) {
    const top = stack[stack.length - 1];
    if (top !== undefined && top[0] === ch) {
      top[1] += 1;
      if (top[1] >= k) stack.pop();
    } else {
      stack.push([ch, 1]);
    }
  }
  let res = "";
  for (const pair of stack) res += pair[0].repeat(pair[1]);
  return res;
}
